before.render:
(v, row) => (
      <SoftStatusLabel label={(row as PaymentReceipt).statusName} tone={RECEIPT_TONE[v as number] ?? 'draft'} />
    )

(v, row) => (
      <SoftStatusLabel label={(row as ReconciliationStatement).statusName} tone={ST_TONE[v as number] ?? 'draft'} />
    )

(_v, r) => {
      const s = statusOf(r)
      return (
        <span className="flex flex-wrap items-center gap-1">
          <SoftStatusLabel label={s.label} tone={s.tone} />
          {/* 已记账但调整凭证没生成：这是唯一需要再点一次的状态，必须显式标出来 */}
          {r.voucherPending && <SoftStatusLabel label="凭证待生成" tone="danger" />}
          {r.voucherNotRequired && <SoftStatusLabel label={r.bizType === 'supplier_refund' ? zeroProof : '不涉及凭证'} tone="draft" />}
        </span>
      )
    }

(_v, r) => (
      <span className="flex items-center gap-1">
        <SoftStatusLabel label={VOUCHER_STATUS_LABELS[r.status]} tone={statusTone(r.status)} />
        {r.isReversal === 1 && <SoftStatusLabel label="红字" tone="danger" />}
      </span>
    )

(_, row) => (
      <SoftStatusLabel
        label={row.settlementType === SETTLEMENT_TYPE.MONTHLY ? `月结 ${row.paymentTermsDays} 天` : row.settlementTypeName}
        tone={(SETTLEMENT_TYPE_TONE[String(row.settlementType) as keyof typeof SETTLEMENT_TYPE_TONE] ?? 'info') as StatusTone}
      />
    )

(_v, row) => (
        <span>
          <span className="block">{row.dept.managerName || <span className="text-muted-foreground">—</span>}</span>
          {row.dept.managerIsActive === false && !row.dept.managerIsDevelopment && <span className="block text-xs text-destructive-ink">{row.dept.managerName ? '负责人已禁用' : '负责人已删除'}</span>}
        </span>
      )

(_, row) => {
      const r = row as FinanceAccount
      return <SoftStatusLabel label={r.isActive ? '启用' : '停用'} tone={activeTone(r.isActive)} />
    }

(_, row) => {
      const c = row as ExpenseCategory
      return <SoftStatusLabel label={c.isActive ? '启用' : '停用'} tone={activeTone(c.isActive)} />
    }

(_, row) => {
      const c = row as ExpenseClaim
      return <SoftStatusLabel label={c.statusName} tone={c.statusTone as StatusTone} />
    }

(_, row) => {
      const t = row as AccountTransaction
      // 余额调整是人工对平账目的动作，与常规收付款区分开
      return <SoftStatusLabel label={t.bizTypeName} tone={t.bizType === 4 ? 'warning' : 'info'} />
    }

v => {
        const text = String(v ?? '')
        return text
          ? <span className="block min-w-0 whitespace-normal [overflow-wrap:anywhere] " title={text}>{text}</span>
          : <span className="whitespace-nowrap text-muted-foreground">—</span>
      }

(v, row) => {
        const tone = getStatusTone(v)
        return <SoftStatusLabel label={formatOperationResult(row.path, v)} tone={RESULT_TONE[tone]} />
      }

(v, row) => {
      const r = row as PaymentRecord
      // 现结当天到期，逾期信息原本挂在到期日列上；那列换成创建日期后移到这里，避免丢失
      const overdue = r.status !== 3 && r.dueDate && new Date(r.dueDate) < new Date()
      return (
        <div className="flex flex-wrap items-center gap-1.5">
          <SoftStatusLabel label={r.statusName} tone={ST_TONE[v as number] ?? 'draft'} />
          {overdue && <SoftStatusLabel label="已逾期" tone="danger" />}
        </div>
      )
    }

(_, row) => {
        const tone = row.status === 4 ? 'success' : row.status === 5 ? 'danger' : row.status === 1 ? 'draft' : 'active'
        const copy = getWaveClosureCopy(row)
        return (
          <div className="space-y-1">
            <SoftStatusLabel label={WAVE_STATUS_LABEL[row.status]} tone={tone} />
            <p className="text-xs text-muted-foreground">{copy.nextAction}</p>
          </div>
        )
      }

(_, row) => {
      const r = row as PortalStatementRow
      const tone = r.status === 3 ? 'success' : r.status === 2 ? 'active' : 'draft'
      return <SoftStatusLabel label={r.statusName} tone={tone} />
    }

(_, row) => (
        <SoftStatusLabel label={row.status === 1 ? '启用' : '停用'} tone={activeTone(row.status === 1)} />
      )

(v, row) => {
      const record = row as ReconciliationRecord
      const overdue = isOverdue(record)
      // 逾期本身就表示未结清：status=1（未付/未收）且逾期时只显示「已逾期」，不再叠加「未付」；
      // 部分付/部分收仍保留（它比逾期多一层信息）
      const hideBase = overdue && Number(v) === 1
      return (
        <div className="flex flex-wrap items-center gap-1.5">
          {!hideBase && (
            <SoftStatusLabel
              label={record.statusName}
              tone={Number(v) === 3 ? 'success' : Number(v) === 2 ? 'active' : 'draft'}
            />
          )}
          {overdue && <SoftStatusLabel label="逾期" tone="danger" />}
          {type === 1 && record.confirmStatus === 0 && <SoftStatusLabel label="待确认" tone="warning" />}
        </div>
      )
    }

(v, row) => {
      const status = v as number
      const tone = status === 3 ? 'success' : status === 4 ? 'danger' : status === 1 ? 'draft' : 'active'
      return <SoftStatusLabel label={(row as RowType).statusName} tone={tone} />
    }

(_, row) => (
          <div className="space-y-1">
            {barcodeStatusBadge(row)}
            {/* 作废原因跟着**业务状态**走（解释为什么这张条码不能再补打），不跟任务结果混在一起 */}
            {row.voidReason && (
              <div className="text-[11px] leading-4 text-muted-foreground">原因：{row.voidReason}</div>
            )}
          </div>
        )

(v) => {
        const status = v as PdaDeviceStatus
        return <SoftStatusLabel label={STATUS_LABEL[status]} tone={status === 'active' ? 'success' : 'draft'} />
      }

(_, p) => (
        <SoftStatusLabel
          label={p.status === 1 ? '在线' : '离线'}
          tone={activeTone(p.status === 1)}
          onClick={canManagePrinters ? () => { if (managePermissionRef.current) toggleStatus.mutate(p) } : undefined}
        />
      )

(_, p) => (
        <SoftStatusLabel
          label={formatPrinterSource(p.source) || sourceBadgeLabel(p.source)}
          tone={p.source === 'client' ? 'success' : p.source === 'local_desktop' ? 'info' : 'draft'}
          title={p.source ? `原始来源：${p.source}` : undefined}
        />
      )

(_,r)=>(
      <SoftStatusLabel
        label={r.settlementType === SETTLEMENT_TYPE.MONTHLY ? `月结 ${r.paymentTermsDays} 天` : r.settlementTypeName}
        tone={(SETTLEMENT_TYPE_TONE[String(r.settlementType) as keyof typeof SETTLEMENT_TYPE_TONE] ?? 'info') as StatusTone}
      />
    )

(v, row) => {
      const status = v as number
      const tone = status === 4 ? 'success' : status === 5 ? 'danger' : status === 1 ? 'draft' : 'active'
      return <SoftStatusLabel label={(row as TransferOrder).statusName} tone={tone} />
    }

(_, row) => (
        <SoftStatusLabel label={row.roleName} tone={row.roleId === 1 ? 'active' : 'info'} />
      )

(_, row) => (
        <SoftStatusLabel label={row.isActive ? '启用' : '禁用'} tone={activeTone(row.isActive)} />
      )

(_, row) => (
        <SoftStatusLabel label={row.typeName} tone="info" />
      )

(_, row) => (
        <SoftStatusLabel label={row.isActive ? '启用' : '停用'} tone={activeTone(row.isActive)} />
      )

